\foreach \t/\lab in {0/7:20,20/7:40,40/8:00,60/8:20,80/8:40} \node[below,font=\fontsize{8.5}{10}\selectfont] at (\t,0) {\lab};
\foreach \d in {4,8,12,16,20} \node[left,font=\fontsize{8.5}{10}\selectfont] at (0,\d) {$\d$};
\node[below] at (40,-3.6) {Time (am)};
\node[rotate=90] at (-19,11) {Distance from home (km)};
\draw[blue,line width=0.8pt] (0,0)--(20,2)--(40,14)--(50,14)--(80,20);
\foreach \t/\d in {0/0,20/2,40/14,50/14,80/20} \fill[blue] (\t,\d) circle (1.5pt);
\end{tikzpicture}
[/tikz]

